import { FunctionComponent } from 'react';
import { BaseEditor, Descendant, Point, Range } from 'slate';
import { HistoryEditor } from 'slate-history';
import { ReactEditor, RenderElementProps } from 'slate-react';
export type DefaultElement = {
    type: 's';
    children: Descendant[];
};
export type CustomEditor = BaseEditor & ReactEditor & HistoryEditor;
export type CustomElement = Record<string, any> & {
    type: string;
    children: Descendant[];
};
export type CustomText = {
    text: string;
};
export interface BizRenderElementProps extends RenderElementProps {
    editor?: CustomEditor;
    renderVarLabel?: (val: string) => React.ReactNode;
}
export interface ILoading {
    message: string;
    loading: boolean;
}
export interface InsertNodesOptions {
    /** 插入节点位置 */
    at?: Point;
    rules?: Record<string, ITagRule>;
    deletePrefix?: boolean;
}
export interface WrapNodesOptions {
    /** 包裹节点选区范围 */
    selection?: Range;
    /** 未选中内容提示 */
    tip?: string;
    rules?: Record<string, ITagRule>;
}
export type TagType = 'single' | 'double';
export type ISerializeFunction = (value: Descendant[], options: {
    tagRules: Record<string, ITagRule>;
}) => string;
export interface ITagRule {
    code: string;
    out: string[];
    inner: string[];
    name: string;
    isParagraph?: boolean;
    render: FunctionComponent | ((eleProps: BizRenderElementProps) => JSX.Element);
    isInline?: boolean;
    isVoid?: boolean;
    type: TagType;
    serialize?: (node: Descendant, options?: {
        tagRules: Record<string, ITagRule>;
    }, serialize?: ISerializeFunction) => string;
    extOpts?: Record<string, any>;
}
